/** A curated image key, or an absolute URL of an image uploaded through the Media Library (API). */
export type MediaRef = MediaKey | (string & {});

const isKey = (ref: string): ref is MediaKey => Object.prototype.hasOwnProperty.call(media, ref);

/** Resolves a curated key or uploaded URL to an <Image> source. Unknown sizes fall back to 3:2. */
export function resolveMedia(ref: MediaRef): { src: string; w: number; h: number } {
  return isKey(ref) ? media[ref] : { src: ref, w: 2000, h: 1333 };
}

/**
 * Origin of uploaded Media Library images: the API's /media/ route on the NEXT_PUBLIC_API_URL host — the only remote origin
 * next.config.ts allows for next/image (no unrestricted remote domains).
 */
const API_MEDIA_ORIGIN = (() => {
  try {
    return new URL(process.env.NEXT_PUBLIC_API_URL ?? "").origin;
  } catch {
    return null;
  }
})();

/** True only for an uploaded image served by the API's media route (the next/image remotePatterns entry). */
export function isAllowedRemoteImage(url: string, origin: string | null = API_MEDIA_ORIGIN): boolean {
  try {
    const u = new URL(url);
    // A Media Library PDF (24 Nov 2026) is a document, never an image.
    return !!origin && u.origin === origin && u.pathname.startsWith("/media/") && !/\.pdf$/i.test(u.pathname) && !u.username && !u.password;
  } catch {
    return false;
  }
}

/**
 * Image for a CMS-managed slot (e.g. the Hero images): a curated key or an allowed uploaded image; anything else — unset, an
 * unexpected host — falls back to the curated default, so the slot never renders a broken or blocked image.
 */
export function slotImage(ref: MediaRef | undefined, fallback: MediaKey): { src: string; w: number; h: number } {
  if (ref && isKey(ref)) return media[ref];
  if (ref && isAllowedRemoteImage(ref)) return { src: ref, w: 2000, h: 1333 };
  return media[fallback];
}

/**
 * Maps an API media object to a MediaRef. Curated website images (served by this app from
 * /images/work/<key>.webp) map back to their local key so they render exactly as before.
 */
export function toMediaRef(m: { url: string } | null | undefined): MediaRef | undefined {
  if (!m?.url) return undefined;
  let path = m.url;
  try {
    path = new URL(m.url, "http://local").pathname;
  } catch {
    return undefined;
  }
  const key = /^\/images\/work\/([a-z-]+)\.webp$/.exec(path)?.[1];
  if (key && isKey(key)) return key;
  return /^https?:\/\//.test(m.url) && !/\.pdf$/i.test(path) ? m.url : undefined;
}

/**
 * `sizes` for an object-cover image shown in a frame that is NARROWER than the photo (e.g. a 3:4 arch fed with a 16:9 photo): the
 * browser must fetch the photo at the width the frame needs divided by the visible fraction of the photo, otherwise it picks a
 * variant that is too small and the picture is upscaled (the "pictures are still low quality" feedback, 23 Nov 2026).
 * `frame` = frame width / height. Every number followed by vw or px in `sizes` is scaled; photos already narrower than the frame are not.
 */
export function coverSizes(sizes: string, img: { w: number; h: number }, frame: number): string {
  const k = Math.max(1, img.w / img.h / frame);
  return k === 1 ? sizes : sizes.replace(/(\d+(?:\.\d+)?)(vw|px)\b(?![^(]*\))/g, (_m, n: string, u: string) => `${Math.round(Number(n) * k)}${u}`);
}
